$kc .= kanjo_college_head( array( 'chip' => 'Learner stories', 'title' => 'Learner Stories', 'lead' => 'Adult students choose Kanjo College to formalise practical skills, change career paths, or return to professional employment. Read how three students managed their studies within our twelve-week term structure.', 'photo' => 8, 'alt' => 'A wide evening study room with warm lamps and large windows where three people study apart.', 'cap' => 'Stories · Halden', 'idx' => '08' ) );
$kc .= kanjo_college_sec( kanjo_college_sechead( 'Three ways in', 'Three ways in, in full' ) . kanjo_college_cards( array( array( 'n' => 1, 'photo' => 10, 'alt' => 'A woman in her thirties studying accounting notes at a kitchen table.', 'title' => 'Marta Ruiz', 'sub' => 'Evening route', 'note' => 'Working full time as a bookkeeper, Marta chose our evening classes to move toward an assistant accountant role. The 36-hour syllabus and two mock papers gave her steady confidence in ledger reconciliation.', 'note_class' => 'kc-card__story' ), array( 'n' => 2, 'photo' => 11, 'alt' => 'A man in his forties reading an accountancy workbook on a commuter train.', 'title' => 'Daniel Mensah', 'sub' => 'Day route', 'note' => 'After years in retail management, Daniel joined the Monday and Wednesday day classes. Twelve-week terms let him learn management accounting while keeping his weekday responsibilities.', 'note_class' => 'kc-card__story' ), array( 'n' => 3, 'photo' => 12, 'alt' => 'A woman in her fifties at a library carrel with a laptop and a calculator.', 'title' => 'Priya Nair', 'sub' => 'One paper per term', 'note' => 'Returning to work after parental leave, Priya took one paper each term to refresh her skills. Classes of at most sixteen gave her the direct access to her lecturer that she needed.', 'note_class' => 'kc-card__story' ) ), 'kc-cards--stories' ), 'kc-papers kc-stories-cards', '' );
$kc .= kanjo_college_sec( kanjo_college_sechead( 'The full stories', 'What each term looked like' ) . kanjo_college_group( kanjo_college_ruled( 'Marta Ruiz', kanjo_college_h( 'Marta Ruiz: Evening Route', 3 ) . kanjo_college_p( esc_html( 'Marta Ruiz worked as a self-employed bookkeeper in Halden for five years before enrolling at Kanjo College. Seeking to progress into an assistant accountant position, she needed formal training in balance sheet reconciliations, accruals, and statutory adjustments. Marta selected our evening timetable on Tuesdays and Thursdays from 18:30 to 21:00, allowing her to maintain client bookkeeping commitments during the business day. By completing classroom exercises and both scheduled mock examinations, Marta gained the technical grounding and ledger accuracy required to handle complex year-end reconciliations in corporate accounting environments.' ) ) ) . kanjo_college_ruled( 'Daniel Mensah', kanjo_college_h( 'Daniel Mensah: Day Route', 3 ) . kanjo_college_p( esc_html( 'After a decade managing retail store operations, Daniel Mensah decided to transition into financial management. Seeking an intensive learning environment, Daniel enrolled in our daytime timetable, attending classes on Mondays and Wednesdays from 09:30 to 15:30. The structured classroom schedule allowed him to master Management Accounting and Financial Accounting step-by-step. Working with lecturers Tomás Ferreira and Amira Haddad in a cohort of under sixteen students, Daniel learned to calculate variances, prepare operational budgets, and build reliable financial models without interrupting his family commitments during evening hours.' ) ) ) . kanjo_college_ruled( 'Priya Nair', kanjo_college_h( 'Priya Nair: One Paper per Term', 3 ) . kanjo_college_p( esc_html( 'Priya Nair returned to professional accountancy study after an extended parental leave. To balance child care with study demands, Priya decided to take one paper per term, starting with Tax and Payroll before moving to Audit and Assurance. Taking one paper allowed her to dedicate thirty-six class hours per term to lectures and make steady progress through the twelve-week syllabus. With guidance from Grace Okonjo and participation in the week nine mock paper, Priya rebuilt her technical confidence, refreshed her regulatory knowledge, and maintained disciplined study habits.' ) ) ), 'kc-ruledlist sp-stagger' ) . kanjo_college_link( 'Take a place →', '/taking-a-place/' ), 'kc-stories-full', '' );
